from build import build
S={
'epiglottic cartilage':'The most <b>rostral</b> laryngeal cartilage. It flips back over the <b>laryngeal inlet</b> when the dog swallows, so food goes to the esophagus instead.',
'aryepiglottic fold':'A mucosal fold running from the <b>epiglottis</b> to the <b>arytenoid cartilage</b>. It forms the side wall of the laryngeal inlet.',
'thyroid cartilage':'The biggest laryngeal cartilage: a <b>ventral U-shaped trough</b> made of two laminae. Its <b>laryngeal prominence</b> is what you palpate on the neck.',
'rostral cornu':'Projection at the dorsal edge of the thyroid cartilage that points rostrally and <b>articulates with the thyrohyoid bone</b>.',
'caudal cornu':'Projection at the dorsal edge of the thyroid cartilage that points caudally and <b>articulates with the cricoid cartilage</b>.',
'caudal thyroid incisure':'The ventral midline <b>notch</b> in the caudal border of the thyroid cartilage, where the cricothyroid ligament attaches.',
'cricothyroid ligament':'Fills the ventral gap between the <b>thyroid</b> and <b>cricoid</b> cartilages, attaching at the caudal thyroid incisure.',
'cricoid cartilage':'A complete <b>signet ring</b>: narrow ventral <b>arch</b>, wide dorsal <b>lamina</b>. It sits caudal to the thyroid cartilage and in front of the trachea.',
'arytenoid cartilage':'Paired cartilages that sit on the <b>rostral border of the cricoid lamina</b>. Their 4 processes are muscular, vocal, corniculate and cuneiform.',
'muscular process':'The <b>lateral</b> process of the arytenoid. The muscles that open and close the glottis attach here (cricoarytenoideus dorsalis, cricoarytenoideus lateralis, thyroarytenoideus).',
'vocal process':'The <b>ventral</b> process of the arytenoid, where the <b>vocal fold</b> attaches.',
'vocal fold':'Runs from the <b>vocal process of the arytenoid</b> to the <b>midventral thyroid cartilage</b>. It is the caudal of the two folds and sits caudal to the ventricle.',
'corniculate process':'The <b>dorsal</b> horn of the arytenoid. It forms the caudal edge of the laryngeal inlet.',
'cuneiform process':'Attached to the arytenoid <b>rostral to the corniculate process</b>. The <b>vestibular fold</b> attaches to it.',
'vestibular fold':'The <b>rostral</b> fold, running from the cuneiform process. Order down the airway: vestibular fold, then ventricle, then vocal fold.',
'laryngeal ventricle':'The pouch <b>between the vestibular fold and the vocal fold</b>.',
'glottis':'The voice-producing part of the larynx: <b>both vocal folds + the vocal processes + the rima glottidis</b>.',
'rima glottidis':'Just the <b>gap</b> through the glottis, between the vocal folds. The cricoarytenoideus dorsalis widens it.',
'cricothyroid muscle':'The "bow tie" on the <b>ventral</b> larynx, from the cricoid to the thyroid cartilage. It tenses the vocal folds and is the only laryngeal muscle supplied by the <b>cranial laryngeal nerve</b>.',
'cricoarytenoideus dorsalis':'Runs from the <b>dorsal cricoid lamina</b> to the <b>muscular process</b>. It is the <b>only abductor</b>: it opens the rima glottidis. When it is paralyzed, you get laryngeal paralysis.',
'cricoarytenoideus lateralis':'Runs from the <b>lateral cricoid arch</b> to the <b>muscular process</b>. It <b>adducts</b>, which closes the rima glottidis.',
'thyroarytenoideus':'The parent muscle from the thyroid cartilage to the <b>muscular process</b>. It splits into <b>vocalis</b> (medial) and <b>ventricularis</b> (rostral) and adducts the glottis.',
'vocalis':'The <b>medial</b> part of the thyroarytenoideus. It lies inside the vocal fold, next to the vocal ligament.',
'vocal ligament':'The ligament that forms the <b>free edge of the vocal fold</b>, from the vocal process to the thyroid cartilage.',
'auricular cartilage':'The cartilage that shapes the <b>pinna</b> (ear flap) and rolls into a funnel for the vertical ear canal.',
'tragus':'A thick, square plate of auricular cartilage on the <b>rostral side of the ear canal opening</b>, opposite the antihelix.',
'marginal cutaneous sac':'A small <b>skin pouch on the lateral margin of the ear</b>. It is easier to find on your cadaver than in pictures.',
'tympanic membrane':'The eardrum, at the <b>deep end of the external acoustic meatus</b>. It separates the outer ear from the middle ear (tympanic bulla).',
'annular cartilage':'A <b>ring of cartilage</b> linking the auricular cartilage to the bony <b>external acoustic meatus</b>.',
'temporalis muscle':'The biggest jaw-closer. It fills the <b>temporal fossa</b> and inserts on the <b>coronoid process</b> of the mandible.',
'masseter muscle':'A jaw-closer on the <b>lateral side of the mandible</b>, from the <b>zygomatic arch</b> to the <b>masseteric fossa</b>.',
'zygomatic salivary gland':'Sits in the <b>ventral orbit</b>, medial to the zygomatic arch. You see it once the arch is removed. Its ducts open into the mouth near the last upper molar.',
'medial pterygoid muscle':'A jaw-closer from the <b>pterygopalatine fossa</b> to the <b>medial side of the mandible ramus</b> and angular process.',
'lateral pterygoid muscle':'A smaller jaw-closer next to the medial pterygoid, from the pterygopalatine fossa to the <b>condylar process</b>. Your lab does not ask you to separate the two.',
'digastricus':'The <b>only jaw-opener</b>. It runs from the <b>paracondylar process</b> to the <b>ventral border of the mandible</b> and has a tendinous intersection in the middle.',
'styloglossus':'An extrinsic tongue muscle from the <b>stylohyoid bone</b> to the tongue. It <b>retracts</b> the tongue.',
'hyoglossus':'An extrinsic tongue muscle from the <b>basihyoid and thyrohyoid</b> to the tongue. It <b>retracts and depresses</b> the tongue. The hypoglossal nerve runs on its lateral surface.',
'genioglossus':'A fan-shaped extrinsic tongue muscle from the <b>chin (medial mandible)</b> into the tongue. It <b>protrudes and depresses</b> the tongue.',
'sternohyoideus':'A strap muscle from the <b>sternum to the basihyoid</b>. It pulls the hyoid and tongue <b>caudally</b>.',
'thyrohyoideus':'From the <b>thyroid cartilage</b> to the <b>thyrohyoid bone</b>. It pulls the larynx and hyoid toward each other.',
'mylohyoideus':'A <b>sling under the tongue</b> between the two halves of the mandible. It raises the floor of the mouth and tongue. The hypoglossal nerve runs deep to it.',
'geniohyoideus':'From the <b>chin to the basihyoid</b>, deep to the mylohyoideus. It pulls the hyoid <b>rostrally</b>.',
}
build(30,'Larynx, ear, tongue + hyoid muscles',S)
